-- game/states/world_map_state.lua
-- Debug: full-screen view of a world map generated by systems/map_generator.lua.
--
-- Pushed from the debug trader dialogue ("Show me the world map (debug).").
-- The map is generated in-memory (no file I/O) via MapGenerator.generateWorld
-- and cached so reopening the view is instant. Esc (or Backspace) pops back
-- to the dialogue.

local WorldMapState = {}

local StateManager = require("core.state_manager")
local GameContext = require("game.game_context")
local MapGenerator = require("systems.map_generator")

local generated = nil    -- result of MapGenerator.generateWorld(...)
local baseImage = nil    -- love.graphics.Image built from generated.base
local overlayImage = nil -- love.graphics.Image built from generated.overlay

-- Camera: zoom 1 = normal (1:1) resolution. camX/camY = top-left of the view
-- in map-pixel coordinates.
local zoom = 1
local camX, camY = 0, 0
local MIN_ZOOM, MAX_ZOOM = 0.2, 8

-- Readable names for the gameplay biome labels (see systems/map_generator.lua).
local BIOME_NAMES = {
    ocean   = "Ocean",
    beach   = "Beach",
    cliff   = "Cliffs",
    snow    = "Snowy Peaks",
    mountain = "Mountains",
    hills   = "Hills",
    desert  = "Desert",
    plains  = "Plains",
    forest  = "Forest",
    marsh   = "Marsh",
    marsh_lake = "Marsh Lake",
}

-- Biome at the screen centre, looked up in the (sample-resolution) biome grid.
local function centerBiome()
    local g = generated
    if not g then
        return nil
    end
    local sw, sh = love.graphics.getDimensions()
    local mx = camX + (sw / 2) / zoom  -- map pixel at screen centre
    local my = camY + (sh / 2) / zoom
    local ux = g.targetW / g.sampleW
    local uy = g.targetH / g.sampleH
    local sx = math.max(1, math.min(g.sampleW, math.floor(mx / ux + 0.5)))
    local sy = math.max(1, math.min(g.sampleH, math.floor(my / uy + 0.5)))
    local b = g.biome[sy] and g.biome[sy][sx]
    if not b then
        return "?"
    end
    return BIOME_NAMES[b] or (b:sub(1, 1):upper() .. b:sub(2))
end

local function clampCamera()
    local g = generated
    if not g then
        return
    end
    local sw, sh = love.graphics.getDimensions()
    local vw, vh = sw / zoom, sh / zoom
    camX = math.max(0, math.min(camX, math.max(0, g.targetW - vw)))
    camY = math.max(0, math.min(camY, math.max(0, g.targetH - vh)))
end

local function resetCamera()
    local g = generated
    if not g then
        return
    end
    zoom = 1
    local sw, sh = love.graphics.getDimensions()
    camX = (g.targetW - sw / zoom) / 2
    camY = (g.targetH - sh / zoom) / 2
    clampCamera()
end

-- Zoom around a screen point (default: screen centre), keeping that point's
-- map position fixed on screen.
local function setZoom(z, cx, cy)
    if not generated then
        return
    end
    z = math.max(MIN_ZOOM, math.min(MAX_ZOOM, z))
    local sw, sh = love.graphics.getDimensions()
    local px, py = cx or sw / 2, cy or sh / 2
    local mx = camX + px / zoom
    local my = camY + py / zoom
    zoom = z
    camX = mx - px / zoom
    camY = my - py / zoom
    clampCamera()
end

function WorldMapState.enter(params)
    params = params or {}

    local map = GameContext.data.currentMap
    local seed = (map and map.worldGen and map.worldGen.seed) or MapGenerator.defaultSeed
    local sizeW = (map and map.width) or MapGenerator.defaultWidth
    local sizeH = (map and map.height) or MapGenerator.defaultHeight

    -- Accept a pre-generated world (used by the standalone self-test viewer);
    -- otherwise regenerate only when the seed/size changed (cached after that).
    if params.world then
        generated = params.world
        baseImage = nil
        overlayImage = nil
    elseif not generated
        or generated.seed ~= seed
        or generated.targetW ~= sizeW
        or generated.targetH ~= sizeH then
        generated = MapGenerator.generateWorld(seed, sizeW, sizeH, MapGenerator.defaultDetail)
        baseImage = nil
        overlayImage = nil
    end

    resetCamera()
end

function WorldMapState.exit()
    -- Keep the cache; it is cheap to hold and makes reopen instant.
end

local function drawMap()
    local g = generated
    if not g then
        return
    end

    if not baseImage then
        baseImage = love.graphics.newImage(g.base)
        baseImage:setFilter("linear", "linear")
    end
    if not overlayImage then
        overlayImage = love.graphics.newImage(g.overlay)
        overlayImage:setFilter("linear", "linear")
    end

    -- Map is drawn under a camera transform: zoom (1 = normal res) then pan by
    -- camX/camY, so WASD/zoom move through the full-resolution image.
    local ux = g.targetW / g.sampleW
    local uy = g.targetH / g.sampleH

    love.graphics.push()
    love.graphics.scale(zoom)
    love.graphics.translate(-camX, -camY)

    love.graphics.setColor(1, 1, 1, 1)
    love.graphics.draw(baseImage, 0, 0)
    -- painted mountains + trees on top
    love.graphics.draw(overlayImage, 0, 0)

    -- rivers (sample coords -> map pixels via ux/uy), drawn under the camera
    if #g.rivers > 0 then
        love.graphics.setColor(62 / 255, 92 / 255, 148 / 255)
        love.graphics.setLineWidth(math.max(1, ux * 0.6))
        love.graphics.setLineStyle("smooth")
        for _, path in ipairs(g.rivers) do
            local pts = {}
            for _, q in ipairs(path) do
                pts[#pts + 1] = (q.x - 0.5) * ux
                pts[#pts + 1] = (q.y - 0.5) * uy
            end
            if #pts >= 4 then
                love.graphics.line(pts)
            end
        end
    end

    love.graphics.pop()
end

function WorldMapState.draw()
    local sw, sh = love.graphics.getDimensions()
    love.graphics.clear(0.06, 0.07, 0.12)

    if generated then
        drawMap()
    else
        love.graphics.setColor(1, 1, 1, 1)
        love.graphics.print("Generating world map...", sw / 2 - 80, sh / 2)
    end

    -- crosshair at the screen centre + the biome under it
    local cx, cy = sw / 2, sh / 2
    local arm, t = 14, 2
    love.graphics.setColor(0, 0, 0, 0.75)  -- dark outline so it shows on any terrain
    love.graphics.setLineWidth(t + 2)
    love.graphics.line(cx - arm, cy, cx + arm, cy)
    love.graphics.line(cx, cy - arm, cx, cy + arm)
    love.graphics.setColor(1, 1, 1, 1)     -- bright core
    love.graphics.setLineWidth(t)
    love.graphics.line(cx - arm, cy, cx + arm, cy)
    love.graphics.line(cx, cy - arm, cx, cy + arm)
    love.graphics.setLineWidth(1)

    local bname = centerBiome()
    if bname then
        local btext = "Biome: " .. bname
        local bw = love.graphics.getFont():getWidth(btext)
        local by = cy + arm + 8
        love.graphics.setColor(0, 0, 0, 0.6)
        love.graphics.rectangle("fill", cx - bw / 2 - 8, by, bw + 16, 20)
        love.graphics.setColor(0.95, 0.93, 0.85)
        love.graphics.print(btext, cx - bw / 2, by + 3)
    end

    -- dark header/footer bars for the overlay text
    love.graphics.setColor(0, 0, 0, 0.55)
    love.graphics.rectangle("fill", 0, 0, sw, 28)
    love.graphics.rectangle("fill", 0, sh - 24, sw, 24)

    local seed = generated and generated.seed or MapGenerator.defaultSeed
    love.graphics.setColor(0.95, 0.93, 0.85)
    love.graphics.print(string.format("World Map (generated) — seed %d", seed), 12, 8)
    love.graphics.print("WASD/arrows: move   -/+ or wheel: zoom   Esc: close", 12, sh - 18)

    -- prominent zoom readout, top-right (updates as you zoom)
    local ztext = string.format("%.0f%%", zoom * 100)
    local zw = love.graphics.getFont():getWidth(ztext)
    love.graphics.setColor(0, 0, 0, 0.6)
    love.graphics.rectangle("fill", sw - zw - 20, 5, zw + 14, 20)
    love.graphics.setColor(0.98, 0.9, 0.55) -- amber, high visibility
    love.graphics.print(ztext, sw - zw - 13, 7)
end

function WorldMapState.update(dt)
    if not generated then
        return
    end
    local speed = 700 / zoom -- map px per second (constant speed on the map)
    local dx, dy = 0, 0
    if love.keyboard.isDown("d", "right") then dx = dx + 1 end
    if love.keyboard.isDown("a", "left") then dx = dx - 1 end
    if love.keyboard.isDown("s", "down") then dy = dy + 1 end
    if love.keyboard.isDown("w", "up") then dy = dy - 1 end
    if dx ~= 0 or dy ~= 0 then
        camX = camX + dx * speed * dt
        camY = camY + dy * speed * dt
        clampCamera()
    end
end

function WorldMapState.keypressed(key)
    if key == "escape" or key == "backspace" then
        StateManager.pop()
    elseif key == "=" or key == "kp+" then
        setZoom(zoom * 1.25)
    elseif key == "-" or key == "kp-" then
        setZoom(zoom / 1.25)
    end
end

function WorldMapState.wheelmoved(x, y)
    if not generated then
        return
    end
    if y > 0 then
        setZoom(zoom * 1.25, love.mouse.getX(), love.mouse.getY())
    elseif y < 0 then
        setZoom(zoom / 1.25, love.mouse.getX(), love.mouse.getY())
    end
end

return WorldMapState
